<template><div class="app-container"><el-table v-loading="loading" :data="rows" border height="700"><el-table-column v-for="key in columns" :key="key" :prop="key" :label="key" min-width="120" /></el-table></div></template>
<script setup name="FutureResearch">import {computed,ref} from 'vue';import{listFutureResearch}from '@/api/future/history';const r=useRoute(),kind=computed(()=>r.path.includes('warehouse')?'warehouse':'positions'),columns=computed(()=>kind.value==='warehouse'?['thscode','trade_date','amount','amount_change','equivalent_lots']:['trade_date','thscode','company_name','long_position','long_position_change','short_position','short_position_change','net_position','net_position_change']),rows=ref([]),loading=ref(true);listFutureResearch(kind.value).then(x=>rows.value=x.data||[]).finally(()=>loading.value=false)</script>
